from itertools import product
from math import exp
sigmoid=lambda t:1/(1+exp(-t))
p_hv={(0,0):1/6,(0,1):1/3,(1,0):1/3,(1,1):1/6}
joint={}
for h,v,c,r,y in product([0,1],repeat=5):
 pr=sigmoid(.75*h+.5*c)
 py=sigmoid(-.5+2.5*v+1.75*c)
 joint[h,v,c,r,y]=p_hv[h,v]*.5*(pr if r else 1-pr)*(py if y else 1-py)
def py_given(**kw):
 idx={'h':0,'v':1,'c':2,'r':3}
 rows=[(k,p) for k,p in joint.items() if all(k[idx[s]]==value for s,value in kw.items())]
 return sum(p*k[4] for k,p in rows)/sum(p for k,p in rows)
print('Checks from the manuscript SCM, integrating out U1 and U2:')
for h in [0,1]:
 print(f'P(Y=1 | H={h}) = {py_given(h=h):.6f}')
for c in [0,1]:
 for r in [0,1]:
  print(f'P(Y=1 | C={c}, R={r}) = {py_given(c=c,r=r):.6f}')
print('Reported bird split sizes sum to',2849+520+529,'versus stated 3538')
print('Reported X-ray accuracy times 50 =',.7455*50)
PY"
